package com.eelab.rflab.protocol

import com.eelab.rflab.ota.OtaGolden
import com.eelab.rflab.ota.hexToBytes
import com.eelab.rflab.ota.readU32Le
import com.eelab.rflab.ota.toHex
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Byte-exact checks of the app's OTA encoder/decoder against the golden
 * vectors generated by `esp32c3-cc1101-lab/ota/ota_ref.py` (committed under
 * test resources). Every command packet must match both the raw packet bytes
 * (post-CRC, pre-COBS) and the wire bytes (COBS body + `0x00` delimiter), and
 * every `*_resp` vector must decode into the expected [OtaResponse] fields.
 */
class OtaCodecVectorTest {

    private val vec = OtaGolden.parsed

    // --- command encoding (raw + wire equality against the vectors) ----------

    @Test
    fun `hello command matches the golden vector`() {
        assertGoldenCommand(vec.hello, PacketCodec.encodeOtaCommand(OtaCommand.hello()))
    }

    @Test
    fun `begin command matches the golden vector`() {
        val sha256 = OtaAuth.sha256(vec.image)
        assertEquals(vec.imageSha256Hex, sha256.toHex())
        val command = OtaCommand.begin(
            size = vec.image.size.toLong(),
            sha256 = sha256,
            mac = OtaAuth.beginMac(vec.secret, vec.nonce, vec.image.size.toLong(), sha256),
        )
        assertGoldenCommand(vec.begin, PacketCodec.encodeOtaCommand(command))
    }

    @Test
    fun `every chunk command matches its golden vector`() {
        assertEquals(vec.image.size.toLong(), 1000L)
        assertEquals(6, vec.chunks.size)
        for (chunkVec in vec.chunks) {
            val offset = chunkVec.offset
            val data = vec.image.copyOfRange(offset.toInt(), minOf(
                offset.toInt() + vec.maxChunk,
                vec.image.size,
            ))
            val command = OtaCommand.chunk(offset, data)
            val encoded = PacketCodec.encodeOtaCommand(command)
            assertEquals("offset $offset", chunkVec.rawHex, encoded.toHex())
            assertEquals(
                "offset $offset",
                vec.chunks.first { it.offset == offset }.wireHex,
                wireOf(encoded).toHex(),
            )
        }
    }

    @Test
    fun `end command matches the golden vector`() {
        assertGoldenCommand(vec.end, PacketCodec.encodeOtaCommand(OtaCommand.end()))
    }

    @Test
    fun `abort command matches the golden vector`() {
        assertGoldenCommand(vec.abort, PacketCodec.encodeOtaCommand(OtaCommand.abort()))
    }

    @Test
    fun `bootloader command matches the golden vector`() {
        val command = OtaCommand.bootloader(
            OtaAuth.bootloaderMac(vec.secret, vec.nonce),
        )
        assertGoldenCommand(vec.bootloader, PacketCodec.encodeOtaCommand(command))
    }

    @Test
    fun `bad_mac_begin command matches the golden vector`() {
        // bad_mac_begin is the same image with an all-zeros secret.
        val zeroSecret = ByteArray(32)
        val sha256 = OtaAuth.sha256(vec.image)
        val command = OtaCommand.begin(
            size = vec.image.size.toLong(),
            sha256 = sha256,
            mac = OtaAuth.beginMac(zeroSecret, vec.nonce, vec.image.size.toLong(), sha256),
        )
        assertGoldenCommand(vec.badMacBegin, PacketCodec.encodeOtaCommand(command))
    }

    // --- response decoding ---------------------------------------------------

    @Test
    fun `hello_resp_ok decodes into caps, max_chunk, slot and nonce`() {
        val response = decodePacket(vec.helloRespOk.rawHex) as OtaResponse
        assertEquals(OtaOps.HELLO, response.op)
        assertEquals(OtaStatus.OK, response.status)

        val info = response.helloInfo()!!
        assertEquals(1, info.caps)
        assertEquals(192, info.maxChunk)
        assertEquals(0x1F0000L, info.slotSize)
        assertEquals(vec.nonce.toHex(), info.nonce.toHex())
    }

    @Test
    fun `begin_resp_ok decodes into an empty OK for op BEGIN`() {
        val response = decodePacket(vec.beginRespOk.rawHex) as OtaResponse
        assertEquals(OtaOps.BEGIN, response.op)
        assertEquals(OtaStatus.OK, response.status)
        assertEquals(0, response.payload.size)
    }

    @Test
    fun `chunk responses decode into next_offset values`() {
        val ok = decodePacket(vec.chunkRespFirst.rawHex) as OtaResponse
        assertEquals(OtaOps.CHUNK, ok.op)
        assertEquals(OtaStatus.OK, ok.status)
        assertEquals(192L, ok.chunkNextOffset())

        val badOffset = decodePacket(vec.chunkRespBadOffset.rawHex) as OtaResponse
        assertEquals(OtaOps.CHUNK, badOffset.op)
        assertEquals(OtaStatus.BAD_OFFSET, badOffset.status)
        assertEquals(192L, badOffset.chunkNextOffset())
    }

    @Test
    fun `end_resp_ok decodes into an empty OK for op END`() {
        val response = decodePacket(vec.endRespOk.rawHex) as OtaResponse
        assertEquals(OtaOps.END, response.op)
        assertEquals(OtaStatus.OK, response.status)
        assertEquals(0, response.payload.size)
    }

    // --- echo/round-trip ------------------------------------------------------

    @Test
    fun `decoded command packets echo the built ones`() {
        val sha256 = OtaAuth.sha256(vec.image)
        val begin = OtaCommand.begin(vec.image.size.toLong(), sha256, ByteArray(32))
        val decodedBegin = decodePacket(vec.begin.rawHex) as OtaCommand
        // The golden MAC differs from a zero-secret BEGIN above, so compare
        // fields against the vector payload instead: this asserts the decoder
        // reads the same op/payload that ota_ref.py wrote.
        assertEquals(OtaOps.BEGIN, decodedBegin.op)
        assertEquals(vec.image.size.toLong(), readU32Le(decodedBegin.payload, 0))
        assertEquals(
            vec.imageSha256Hex,
            decodedBegin.payload.copyOfRange(4, 36).toHex(),
        )

        val chunk = OtaCommand.chunk(192, vec.image.copyOfRange(192, 384))
        val decodedChunk = decodePacket(
            PacketCodec.encodeOtaCommand(chunk).toHex(),
        ) as OtaCommand
        assertEquals(chunk, decodedChunk)
    }

    // --- helpers --------------------------------------------------------------

    /** raw and wire hex must both reproduce the vector. */
    private fun assertGoldenCommand(expected: OtaGolden.PacketVec, actualRaw: ByteArray) {
        assertEquals("raw", expected.rawHex, actualRaw.toHex())
        assertEquals("wire", expected.wireHex, wireOf(actualRaw).toHex())
    }

    /** Applies the transport framing: COBS body + `0x00` delimiter. */
    private fun wireOf(raw: ByteArray): ByteArray = Cobs.encode(raw) + byteArrayOf(0)

    private fun decodePacket(hex: String): Packet {
        val result = PacketCodec.decode(hex.hexToBytes())
        if (result !is PacketDecodeResult.Success) {
            throw AssertionError("vector packet did not decode: $result")
        }
        return result.packet
    }
}
